package android.widget;import android.content.Context;import android.view.View;import android.graphics.drawable.*;import android.graphics.drawable.shapes.RectShape;public class ProgressBar extends View {protected int progress,max=100;private final Drawable drawable=new ShapeDrawable(new RectShape());public ProgressBar(Context c){super(c);}public void setProgress(int p){progress=Math.max(0,Math.min(p,max));emit("progress",progress);}public int getProgress(){return progress;}public Drawable getProgressDrawable(){return drawable;}}